{"action":"edit","path":"snap_core.py","old_text":"","new_text":"import numpy as np
from scipy.sparse.linalg import LinearOperator, eigsh

def matrix_free_spectral_embedding(counts, n_components, random_state=None):
    if not isinstance(counts, np.ndarray) or counts.ndim != 2:
        raise ValueError("counts must be a 2D numpy array")
    if not np.isfinite(counts).all():
        raise ValueError("counts contains nonfinite values")
    if (counts < 0).any():
        raise ValueError("counts contains negative values")
    if np.any(np.all(counts == 0, axis=1)):
        raise ValueError("counts contains all-zero rows")
    n, m = counts.shape
    if not (1 <= n_components < n):
        raise ValueError("n_components must be between 1 and n_cells-1")
    df = (counts > 0).sum(axis=0)
    idf = np.log(n / (1.0 + df))
    X = counts * idf
    row_norms = np.linalg.norm(X, axis=1, keepdims=True)
    if (row_norms == 0).any():
        raise ValueError("Row cannot be L2-normalized after IDF scaling")
    X = X / row_norms
    ones = np.ones(n)
    d = X @ (X.T @ ones) - 1.0
    if (d <= 0).any():
        raise ValueError("Nonpositive degree detected")
    D_inv = d ** (-0.5)
    X_tilde = X * D_inv[:, None]
    def matvec(v):
        return X_tilde @ (X_tilde.T @ v) - D_inv.astype(X.dtype) * v
    A = LinearOperator((n, n), matvec=matvec, dtype=X.dtype)
    if random_state is not None:
        rng = np.random.RandomState(random_state)
        v0 = rng.uniform(size=n)
    else:
        v0 = None
    eigenvalues, eigenvectors = eigsh(A, k=n_components, which='LM', v0=v0)
    eigenvalues = eigenvalues[::-1]
    eigenvectors = eigenvectors[:, ::-1]
    return eigenvalues, eigenvectors
